const listContacts = `-- name: ListContacts :many
SELECT contact.id, contact.company_id, contact.first_name, contact.last_name, contact.title, contact.email,
  contact.email_check_status, contact.phone, contact.mobile, contact.status, contact.role, contact.updated_at,
  m.status AS mailbox_status, m.checked_at AS mailbox_checked_at, l.current_job AS linkedin_current, l.joined AS linkedin_joined, l.left_on AS linkedin_left,
  l.checked_at AS linkedin_checked_at, coalesce(l.matched_by_name, false)::boolean AS linkedin_matched_by_name
FROM contact LEFT JOIN contact_mailbox_check m ON m.contact_id = contact.id AND m.email = contact.email
  LEFT JOIN LATERAL (
    SELECT lc.current_job, lc.joined, lc.left_on, lc.checked_at, lc.matched_by_name FROM contact_linkedin_check lc
    WHERE lc.contact_id = contact.id AND lc.status = 'observed' ORDER BY lc.checked_at DESC LIMIT 1
  ) l ON true
WHERE ($1::text IS NULL OR contact.id < $1::text)
  AND ($2::text IS NULL OR contact.company_id = $2::text)
  AND ($3::text IS NULL OR contact.status = $3::text)
  AND ($4::text IS NULL OR contact.role = $4::text)
  AND (NOT $5::boolean OR contact.role IS NULL)
  AND ($6::text[] IS NULL OR contact.id = ANY ($6::text[])) -- a folder's
  AND ($7::text IS NULL
       OR CASE WHEN $8::boolean
            THEN app_normalize_text($7::text) <% contact.name_text
            ELSE contact.search_text LIKE ALL (app_search_patterns($7::text))
              OR contact.phone_digits LIKE '%' || app_phone_key($7::text) || '%'
          END)
  -- A boolean search (boolsearch's query for to_tsquery).
  -- The expression of contact_search_doc_idx (00115), so the index answers.
  AND ($9::text IS NULL
       OR app_search_doc(contact.first_name || ' ' || contact.last_name, contact.title, contact.email) @@ to_tsquery('english', $9::text))
ORDER BY CASE WHEN $8::boolean THEN word_similarity(app_normalize_text(coalesce($7::text, '')), contact.name_text) END DESC, contact.id DESC
LIMIT $10
`

type ListContactsParams struct {
	Cursor       *string
	CompanyID    *string
	Status       *string
	Role         *string
	RoleNotSet   bool
	InIds        []string
	Query        *string
	SimilarNames bool
	Tsquery      *string
	RowLimit     int32
}

type ListContactsRow struct {
	ID                    string
	CompanyID             string
	FirstName             string
	LastName              string
	Title                 *string
	Email                 *string
	EmailCheckStatus      *string
	Phone                 *string
	Mobile                *string
	Status                string
	Role                  *string
	UpdatedAt             time.Time
	MailboxStatus         *string
	MailboxCheckedAt      *time.Time
	LinkedinCurrent       *bool
	LinkedinJoined        *string
	LinkedinLeft          *string
	LinkedinCheckedAt     *time.Time
	LinkedinMatchedByName bool
}

// Newest first, keyset pagination on id (IDs sort by creation time).
// With @similar, names like the query (typos) instead, the closest first.
// With @role_not_set, only contacts without a role.
func (q *Queries) ListContacts(ctx context.Context, arg ListContactsParams) ([]ListContactsRow, error) {
	rows, err := q.db.Query(ctx, listContacts,
		arg.Cursor,
		arg.CompanyID,
		arg.Status,
		arg.Role,
		arg.RoleNotSet,
		arg.InIds,
		arg.Query,
		arg.SimilarNames,
		arg.Tsquery,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListContactsRow
	for rows.Next() {
		var i ListContactsRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.FirstName,
			&i.LastName,
			&i.Title,
			&i.Email,
			&i.EmailCheckStatus,
			&i.Phone,
			&i.Mobile,
			&i.Status,
			&i.Role,
			&i.UpdatedAt,
			&i.MailboxStatus,
			&i.MailboxCheckedAt,
			&i.LinkedinCurrent,
			&i.LinkedinJoined,
			&i.LinkedinLeft,
			&i.LinkedinCheckedAt,
			&i.LinkedinMatchedByName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

